<!doctype html><html><head><meta charset="utf-8"><title>Mermaid render</title>
<style>html,body{margin:0;padding:0;background:#fff;color:#111}#pg{box-sizing:border-box;padding:24px;font:12px sans-serif}
#hdr{font-weight:bold;height:26px;overflow:hidden;white-space:nowrap}#d{overflow:hidden;position:relative}#d svg{position:absolute;max-width:none!important}</style>
</head><body><div id="pg"><div id="hdr">loading</div><div id="d"></div></div>
<script type="module">
const qs = new URLSearchParams(location.search);
const { default: mermaid } = await import('https://cdn.jsdelivr.net/npm/mermaid@' + (qs.get('mm') || '12') + '/dist/mermaid.esm.min.mjs');
const cfg = { startOnLoad: false, theme: 'default', htmlLabels: false, flowchart: { useMaxWidth: false, curve: 'linear', htmlLabels: false }, sequence: { useMaxWidth: false, wrap: qs.get('wrap') !== '0' }, er: { useMaxWidth: false }, state: { useMaxWidth: false } };
if (qs.get('layout')) { cfg.layout = qs.get('layout'); }
if (qs.get('reg') === 'tidy') { const tidy = await import('https://cdn.jsdelivr.net/npm/@mermaid-js/layout-tidy-tree@1/+esm'); mermaid.registerLayoutLoaders(tidy.default); }
mermaid.initialize(cfg);
window.mermaidVersion = mermaid.version ? mermaid.version() : 'unknown';
const PT8 = 96 * 8 / 72, PT12 = 96 * 12 / 72, M = 24, HD = 26;
window.blockCount = blocks.length;
function fontRange(svg) {
  let lo = Infinity, hi = 0;
  for (const el of svg.querySelectorAll('text, tspan, foreignObject span, foreignObject div, foreignObject p')) {
    if (!el.textContent.trim() || (el.children.length && el.tagName !== 'text')) continue;
    const px = parseFloat(getComputedStyle(el).fontSize);
    if (px > 0) { lo = Math.min(lo, px); hi = Math.max(hi, px); }
  }
  return [lo === Infinity ? 16 : lo, hi || 16];
}
window.page = async (n, tile = 0) => {
  const b = blocks[n - 1];
  const d = document.getElementById('d');
  const kind = b.code.trim().split(/\s/)[0];
  const lay = qs.get('layout') || ((kind === 'flowchart' || kind === 'graph' || kind === 'erDiagram') ? 'elk' : 'dagre');
  window.lastLayout = lay;
  const code = '---\nconfig:\n  layout: ' + lay + '\n---\n' + b.code;
  let r; try { r = await mermaid.render('p' + n + '_' + Date.now(), code); } catch (e) { d.textContent = 'RENDER FAIL: ' + (e.message || e); return null; }
  d.innerHTML = r.svg;
  const svg = d.querySelector('svg'); const vb = svg.viewBox.baseVal;
  svg.removeAttribute('width'); svg.style.width = vb.width + 'px'; svg.style.height = vb.height + 'px';
  const [fmin, fmax] = fontRange(svg);
  const land = kind === 'sequenceDiagram' || vb.width >= vb.height;
  const W = land ? 1056 : 816, H = land ? 816 : 1056, AW = W - 2 * M, AH = H - 2 * M - HD;
  const fit = Math.min(AW / vb.width, AH / vb.height);
  const sMin = PT8 / fmin, sMax = PT12 / fmax;
  const conflict = sMin > sMax + 1e-9;
  const s = conflict ? sMin : Math.min(Math.max(fit, sMin), sMax);
  const cols = Math.max(1, Math.ceil(vb.width * s / AW - 1e-6)), rows = Math.max(1, Math.ceil(vb.height * s / AH - 1e-6)), tiles = cols * rows;
  const t = Math.min(tile, tiles - 1), tx = (t % cols) * AW, ty = Math.floor(t / cols) * AH;
  const pg = document.getElementById('pg'); pg.style.width = W + 'px'; pg.style.height = H + 'px';
  d.style.width = AW + 'px'; d.style.height = AH + 'px';
  svg.style.width = (vb.width * s) + 'px'; svg.style.height = (vb.height * s) + 'px'; svg.style.left = (-tx) + 'px'; svg.style.top = (-ty) + 'px';
  const ptLo = (fmin * s * 72 / 96).toFixed(1), ptHi = (fmax * s * 72 / 96).toFixed(1);
  document.getElementById('hdr').textContent = '#' + b.n + '/' + blocks.length + ' line ' + b.line + ' | ' + b.heading + ' | ' + (land ? 'landscape' : 'portrait') + ' | page ' + (t + 1) + ' of ' + tiles + ' (' + cols + 'x' + rows + ') | text ' + ptLo + '-' + ptHi + ' pt' + (conflict ? ' | FONT BAND CONFLICT' : '');
  window.scrollTo(0, 0); document.title = 'page ' + n + '.' + t;
  return { n: b.n, orient: land ? 'L' : 'P', scale: Number(s.toFixed(3)), tiles, cols, rows, ptLo: Number(ptLo), ptHi: Number(ptHi), conflict };
};
window.survey = async () => { const out = []; for (let i = 1; i <= blocks.length; i++) { const r = await window.page(i); out.push(r ? r.n + r.orient + 'x' + r.tiles + '(' + r.ptLo + '-' + r.ptHi + (r.conflict ? '!' : '') + ')' : i + 'FAIL'); } return out.join(' '); };
const esc = (t) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
async function savePng(svgText, W, H, name) {
  const K = 1.5, img = new Image();
  const url = URL.createObjectURL(new Blob([svgText], { type: 'image/svg+xml' }));
  await new Promise((ok, bad) => { img.onload = ok; img.onerror = () => bad(new Error('image load failed ' + name)); img.src = url; });
