async function savePng(svgText, W, H, name) {
  const K = 1.5, img = new Image();
  const url = URL.createObjectURL(new Blob([svgText], { type: 'image/svg+xml' }));
  await new Promise((ok, bad) => { img.onload = ok; img.onerror = () => bad(new Error('image load failed ' + name)); img.src = url; });
  const c = document.createElement('canvas'); c.width = Math.round(W * K); c.height = Math.round(H * K);
  const g = c.getContext('2d'); g.fillStyle = '#fff'; g.fillRect(0, 0, c.width, c.height); g.drawImage(img, 0, 0, c.width, c.height);
  URL.revokeObjectURL(url);
  const blob = await new Promise((ok) => c.toBlob(ok, 'image/png'));
  const res = await fetch('/save/' + name, { method: 'POST', body: blob });
  if (!res.ok) throw new Error('save failed ' + name + ' ' + res.status);
}
window.exportBlock = async (n) => {
  const info = await window.page(n);
  if (!info) return n + ':FAIL';
  const b = blocks[n - 1];
  const src = document.querySelector('#d svg');
  const vb = src.viewBox.baseVal;
  const land = info.orient === 'L', W = land ? 1056 : 816, H = land ? 816 : 1056, AW = W - 2 * M, AH = H - 2 * M - HD, s = info.scale;
  const inner = new XMLSerializer().serializeToString(src);
  const boxes = [];
  for (const el of src.querySelectorAll('g.node, g.cluster, path, line, rect, text, polygon, circle, ellipse')) {
    try { const bb = el.getBBox(); if (bb.width || bb.height) { const m = el.getCTM(), r = src.getCTM().inverse().multiply(m); const p1 = new DOMPoint(bb.x, bb.y).matrixTransform(r), p2 = new DOMPoint(bb.x + bb.width, bb.y + bb.height).matrixTransform(r); boxes.push([Math.min(p1.x, p2.x), Math.min(p1.y, p2.y), Math.max(p1.x, p2.x), Math.max(p1.y, p2.y)]); } } catch (e) { }
  }
  let saved = 0; const skipped = [];
  for (let t = 0; t < info.tiles; t++) {
    const tx = (t % info.cols) * AW, ty = Math.floor(t / info.cols) * AH;
    const vbx = vb.x + tx / s, vby = vb.y + ty / s, vbw = AW / s, vbh = AH / s;
    if (info.tiles > 1 && !boxes.some(([x1, y1, x2, y2]) => x2 > vbx && x1 < vbx + vbw && y2 > vby && y1 < vby + vbh)) { skipped.push(t + 1); continue; }
    saved++;
    const nested = inner.replace(/^<svg\b[^>]*>/, (open) => open
      .replace(/\s(width|height|x|y|viewBox|style)="[^"]*"/g, '')
      .replace('<svg', '<svg x="' + M + '" y="' + (M + HD) + '" width="' + AW + '" height="' + AH + '" viewBox="' + vbx + ' ' + vby + ' ' + vbw + ' ' + vbh + '" preserveAspectRatio="xMinYMin meet"'));
    const hdr = '#' + b.n + '/' + blocks.length + '  line ' + b.line + '  ' + b.heading.replace(/^#+\s*/, '') + '  |  ' + (land ? 'landscape' : 'portrait') + '  |  page ' + (t + 1) + ' of ' + info.tiles + ' (' + info.cols + 'x' + info.rows + ')  |  text ' + info.ptLo + '-' + info.ptHi + ' pt  |  ' + window.lastLayout;
    const page = '<svg xmlns="http://www.w3.org/2000/svg" width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '">'
      + '<rect width="' + W + '" height="' + H + '" fill="#fff"/>'
      + '<text x="' + M + '" y="' + (M + 12) + '" font-family="sans-serif" font-size="11" font-weight="bold" fill="#111">' + esc(hdr) + '</text>'
      + '<rect x="' + M + '" y="' + (M + HD) + '" width="' + AW + '" height="' + AH + '" fill="none" stroke="#ccc"/>'
      + nested + '</svg>';
    await savePng(page, W, H, 'd' + String(b.n).padStart(3, '0') + '-p' + String(t + 1).padStart(2, '0') + '.png');
  }
  return n + ':' + saved + (skipped.length ? '(blank ' + skipped.join(',') + ')' : '');
};
window.exportRange = async (from, to) => { const out = []; for (let i = from; i <= to; i++) { try { out.push(await window.exportBlock(i)); } catch (e) { out.push(i + ':ERR ' + e.message); } } return out.join(' '); };
await window.page(Number(location.hash.slice(1)) || 1);
